function d(r,o){for(const t of r.querySelectorAll("[data-doge-user]"))t.querySelector("button")?.addEventListener("click",()=>{const e=document.createElement("iframe");e.className="video-embed",e.title="DogeCloud video",e.srcdoc=`<!doctype html><html><meta charset="utf-8"><div id="video"></div><script src="https://player.dogecloud.com/js/loader"><\/script><script>new DogePlayer({container:document.getElementById('video'),userId:${Number(t.dataset.dogeUser)},vcode:${JSON.stringify(t.dataset.dogeCode)},autoPlay:false})<\/script></html>`,t.replaceChildren(e),o.addEventListener("abort",()=>e.remove(),{once:!0})},{once:!0,signal:o})}export{d as mount};
